   ```c
   if (mount("proc", "/proc", "proc", MS_NODEV | MS_NOEXEC | MS_NOSUID | MS_RELATIME, NULL) < 0) {
       fuse_log(FUSE_LOG_ERR, "mount(/proc): %m\n");
